package com.dnd.simulator.entity;
import jakarta.persistence.*; import java.time.Instant; import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="world_events") public class WorldEvent {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @Column(nullable=false) private String title; private String type; private String category; private String targetFactionId; private String secondTargetFactionId; private int powerDelta; private int wealthDelta; private int manpowerDelta; private int influenceDelta; private int territoryDelta; @Column(length=2000) private String details; private Instant occurredAt=Instant.now();
 @ManyToOne(optional=false) private World world;
 public WorldEvent(){} public WorldEvent(String t,String type,String category,String target,String d,World w){title=t;this.type=type;this.category=category;targetFactionId=target;details=d;world=w;}
 public String getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getTargetFactionId(){return targetFactionId;} public void setTargetFactionId(String v){targetFactionId=v;} public String getSecondTargetFactionId(){return secondTargetFactionId;} public void setSecondTargetFactionId(String v){secondTargetFactionId=v;} public int getPowerDelta(){return powerDelta;} public void setPowerDelta(int v){powerDelta=v;} public int getWealthDelta(){return wealthDelta;} public void setWealthDelta(int v){wealthDelta=v;} public int getManpowerDelta(){return manpowerDelta;} public void setManpowerDelta(int v){manpowerDelta=v;} public int getInfluenceDelta(){return influenceDelta;} public void setInfluenceDelta(int v){influenceDelta=v;} public int getTerritoryDelta(){return territoryDelta;} public void setTerritoryDelta(int v){territoryDelta=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public Instant getOccurredAt(){return occurredAt;} @JsonIgnore public World getWorld(){return world;} public void setWorld(World w){world=w;}
}
